sys_script_include.script:
var LabBatchReferenceQualifier = Class.create();
LabBatchReferenceQualifier.prototype = {
    initialize: function() {},

    getLabBatches: function(offeringId) {

        // No Offering selected
        if (!offeringId) {
            return 'sys_idISEMPTY';
        }

        // Retrieve selected Course Offering
        var offering = new GlideRecord('x_1790229_edusph_0_course_offering');

        if (!offering.get(offeringId)) {
            return 'sys_idISEMPTY';
        }

        // Get Section associated with Offering
        var sectionId = offering.getValue(
            'section'
        );

        if (!sectionId) {
            return 'sys_idISEMPTY';
        }

        // Return Lab Batches belonging to that Section
        return 'section=' + sectionId;
    },

    type: 'LabBatchReferenceQualifier'
};
